const app = $items("Get Application")[0].json;
const scores = $items("Get Scores")[0]?.json || {};
const weights = $items("Get Evaluation Profile")[0]?.json || {};

// helpers
const toNum = (v, d = 0) => {
  const n = typeof v === 'number' ? v : parseFloat(String(v ?? ''));
  return Number.isFinite(n) ? n : d;
};

// Parse Postgres array text like {"A","B"} -> ["A","B"]
const parsePgArrayText = (v) => {
  if (v == null) return [];
  if (Array.isArray(v)) return v.filter(x => x != null).map(x => String(x).trim()).filter(Boolean);

  const s = String(v).trim();
  if (!s) return [];

  // already JSON array string
  if (s.startsWith('[')) {
    try {
      const arr = JSON.parse(s);
      return Array.isArray(arr) ? arr.map(x => String(x).trim()).filter(Boolean) : [];
    } catch {
      // fall through
    }
  }

  // postgres array text: {"A","B"} or {A,B}
  if (s.startsWith('{') && s.endsWith('}')) {
    const inner = s.slice(1, -1).trim();
    if (!inner) return [];
    return inner
      .split(',')
      .map(x => x.trim().replace(/^"(.*)"$/, '$1')) // remove surrounding quotes
      .map(x => x.replace(/\\"/g, '"'))
      .filter(Boolean);
  }

  // fallback: treat as single item
  return [s];
};

// Ensure an array of strings, even if field is a single string
const toStringArray = (v) => {
  if (v == null) return [];
  if (Array.isArray(v)) return v.filter(x => x != null).map(x => String(x).trim()).filter(Boolean);

  const s = String(v).trim();
  if (!s) return [];
  if (s.startsWith('{') && s.endsWith('}')) return parsePgArrayText(s);
  if (s.startsWith('[')) {
    try {
      const arr = JSON.parse(s);
      return Array.isArray(arr) ? arr.map(x => String(x).trim()).filter(Boolean) : [];
    } catch {
      // fall through
    }
  }
  if (s.includes('\n')) return s.split('\n').map(x => x.trim()).filter(Boolean);
  return [s];
};

// overall score
const overallScore =
  toNum(app.overall_score, NaN) ||
  toNum(app.final_score, 0) ||
  0;

// build scoring dimension: keep old keys + add new keys
const buildDim = (percentRaw, maxPointsRaw) => {
  const percent = Math.max(0, Math.min(100, toNum(percentRaw, 0)));
  const max_points = Math.max(0, toNum(maxPointsRaw, 0));

  const points = +(percent * (max_points / 100)).toFixed(2);
  const bar_percent = max_points > 0 ? +((points / max_points) * 100).toFixed(2) : 0;

  return {
    // OLD contract (frontend likely uses these)
    achieved: points,
    max: max_points,

    // NEW fields
    percent,
    points,
    max_points,
    bar_percent
  };
};

const dimScores = {
  skills: buildDim(scores.score_skills, weights.weight_skills),
  experience: buildDim(scores.score_experience, weights.weight_experience),
  education: buildDim(scores.score_education, weights.weight_education),
  certifications: buildDim(scores.score_certifications, weights.weight_certifications),
  soft_skills: buildDim(scores.score_soft_skills, weights.weight_soft_skills),
  domain_knowledge: buildDim(scores.score_domain_knowledge, weights.weight_domain_knowledge),
  other_requirements: buildDim(scores.score_other_requirements, weights.weight_other_requirements),
};

return [{
  json: {
    application_id: app.application_id,
    candidate_name: app.candidate_name,
    decision: (app.decision || '').toLowerCase(),
    overall_score: overallScore,

    // scoring dimensions (old + new)
    scores: dimScores,

    analysis: {
      summary: scores.evaluation_notes || '',
      cv_skills_matched: scores.cv_skills_matched || '',
      cv_experience_summary: scores.cv_experience_summary || '',
      cv_education_summary: scores.cv_education_summary || '',
      cv_domain_experience: scores.cv_domain_experience || '',
      cv_other_notes: scores.cv_other_notes || '',

      // arrays / normalization
      cv_certifications_found: parsePgArrayText(scores.cv_certifications_found),
      gaps_identified: toStringArray(scores.gaps_identified),
      interview_focus_points: toStringArray(scores.interview_focus_points),
      interview_suggested_questions: parsePgArrayText(scores.interview_suggested_questions),
    },

    raw_ai_response: scores.raw_ai_response || {}
  }
}];
